import{_ as p,r as a,o,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"Section - October CMS - 3.x","titleTemplate":false,"description":"Определение раздела сайта с выделенным URL.","frontmatter":{"subtitle":"Определение раздела сайта с выделенным URL."},"headers":[{"level":2,"title":"Доступные свойства","slug":"доступные-своиства","link":"#доступные-своиства","children":[]},{"level":2,"title":"Базовое использование","slug":"базовое-использование","link":"#базовое-использование","children":[]},{"level":2,"title":"Изменение идентификатора поиска","slug":"изменение-идентификатора-поиска","link":"#изменение-идентификатора-поиска","children":[]},{"level":2,"title":"Проверка существования записи","slug":"проверка-существования-записи","link":"#проверка-существования-записи","children":[]},{"level":2,"title":"Доступ к типу записи","slug":"доступ-к-типу-записи","link":"#доступ-к-типу-записи","children":[]},{"level":2,"title":"Использование полного slug","slug":"использование-полного-slug","link":"#использование-полного-slug","children":[]}],"relativePath":"3.x/ru/cms/components/section.md","filePath":"3.x/ru/cms/components/section.md"}'),u={name:"3.x/ru/cms/components/section.md"};function r(k,n,d,g,m,v){const t=a("pre-heading"),e=a("post-heading");return o(),l("div",null,[s(t),n[0]||(n[0]=c("h1",null,"Section",-1)),s(e),n[1]||(n[1]=i(`<p>Компонент <code>section</code> определяет раздел сайта с привязанной записью. Этот раздел будет использоваться при предварительном просмотре записи из панели администрирования.</p><h2 id="доступные-своиства"><a href="#доступные-своиства" class="header-anchor">#</a> Доступные свойства</h2><p>Компонент поддерживает следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>handle</strong></td><td>Handle <a href="./../tailor/blueprints.html">чертежа записи</a>.</td></tr><tr><td><strong>identifier</strong></td><td>Ключ идентификатора для поиска записи, поддерживаемые значения: <code>slug</code>, <code>fullslug</code> или <code>id</code>. По умолчанию: <code>slug</code></td></tr><tr><td><strong>value</strong></td><td>Значение идентификатора для поиска записи, необязательно. Оставьте пустым для использования ключа идентификатора в качестве имени URL-параметра. Может быть жёстко задано или использовать пользовательский параметр, например: <code>{{ :slug }}</code></td></tr><tr><td><strong>isDefault</strong></td><td>Сделать эту страницу страницей по умолчанию при предварительном просмотре записи. По умолчанию: <code>true</code>.</td></tr></tbody></table></div><h2 id="базовое-использование"><a href="#базовое-использование" class="header-anchor">#</a> Базовое использование</h2><p>Следующий пример создаёт раздел для записи <strong>Blog\\Author</strong> и находит его, используя <a href="./../themes/pages.html">URL-параметр</a> <code>:slug</code> по умолчанию. Имя автора отображается как заголовок через Twig-переменную <code>{{ section.title }}</code>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">author/:slug</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Posts by <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> section<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Когда на одной странице используется несколько секций, псевдоним компонента может назначить другое имя переменной. Следующий псевдоним <strong>author</strong> делает заголовок доступным через Twig-переменную <code>{{ author.title }}</code>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section author</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Posts by <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> author<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><h2 id="изменение-идентификатора-поиска"><a href="#изменение-идентификатора-поиска" class="header-anchor">#</a> Изменение идентификатора поиска</h2><p>Идентификатор по умолчанию — <code>slug</code>, его можно изменить через свойство <code>identifier</code>, например, для поиска записи по столбцу <code>id</code>. Обратите внимание, что URL страницы также меняется на параметр <code>:id</code>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">author/:id</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">id</span>&quot;</span>
</code></pre></div><p>Вы можете жёстко задать поиск идентификатора с помощью свойства <code>value</code>. Например, установка значения <strong>7</strong> покажет запись со статическим поиском.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">author/ceo</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">id</span>&quot;</span>
<span class="token key attr-name">value</span> <span class="token punctuation">=</span> <span class="token value attr-value">7</span>
</code></pre></div><p>Свойство <code>value</code> также принимает внешние параметры. Следующий пример использует URL-параметр <strong>foobar</strong> для поиска записи.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">author/:foobar</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Author</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">id</span>&quot;</span>
<span class="token key attr-name">value</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">{{ :foobar }}</span>&quot;</span>
</code></pre></div><div class="custom-block warning"><p>Предварительный просмотр ссылок и использование <a href="./../../element/form/widget-pagefinder.html">виджета поиска страниц</a> не поддерживают идентификаторы с пользовательскими значениями.</p></div><h2 id="проверка-существования-записи"><a href="#проверка-существования-записи" class="header-anchor">#</a> Проверка существования записи</h2><p>В большинстве случаев вы захотите отобразить страницу 404, если запись не найдена. Это возможно с помощью оператора <code>{% if %}</code> в сочетании с функцией <code>abort(404)</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> author <span class="token operator">is</span> empty <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> abort<span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block tip"><p><a href="./../../markup/function/abort.html">Twig-функция <code>abort()</code></a> используется для отображения страницы 404, когда запись не найдена.</p></div><h2 id="доступ-к-типу-записи"><a href="#доступ-к-типу-записи" class="header-anchor">#</a> Доступ к типу записи</h2><p>При использовании функции <a href="./blueprints.html">Групп контента</a> чертежа записи вы можете получить доступ к коду группы через атрибут <code>content_group</code>. Например, публикация может иметь группу контента <strong>regular_post</strong> и <strong>markdown_post</strong>, где содержимое обрабатывается по-разному.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> post<span class="token punctuation">.</span>content_group <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>markdown_post<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token comment">&lt;!-- Render content as Markdown --&gt;</span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>content<span class="token operator">|</span>md <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token comment">&lt;!-- Render content as HTML --&gt;</span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>content<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="использование-полного-slug"><a href="#использование-полного-slug" class="header-anchor">#</a> Использование полного slug</h2><p>Если тип записи — <code>structure</code>, у неё доступен атрибут <strong>fullslug</strong>. Для использования полного slug в URL страницы он должен быть определён как <a href="./../themes/pages.html">URL-параметр с подстановочным знаком</a>. Свойство <code>identifier</code> компонента должно быть установлено в <strong>fullslug</strong>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/wiki/:fullslug*</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section article</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Wiki\\Article</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">fullslug</span>&quot;</span>
</code></pre></div><p>В качестве альтернативного подхода мы рекомендуем нацеливаться на <strong>id</strong> и размещать его в конце URL. Это позволяет свободно перемещать запись без нарушения ссылок на сайте. Следующий пример показывает, как достичь этого с перенаправлением для ранее использовавшихся URL.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/wiki/:fullslug*/:id</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section article</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Wiki\\Article</span>&quot;</span>
<span class="token key attr-name">identifier</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">id</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> article <span class="token operator">is</span> empty <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> abort<span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">elseif</span> article<span class="token punctuation">.</span>fullslug <span class="token operator">!=</span> this<span class="token punctuation">.</span>param<span class="token punctuation">.</span>fullslug <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> redirect<span class="token punctuation">(</span>this<span class="token operator">|</span>page<span class="token punctuation">(</span><span class="token punctuation">{</span> fullslug<span class="token punctuation">:</span> article<span class="token punctuation">.</span>fullslug <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">301</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token comment">&lt;!-- Contents here --&gt;</span>
</code></pre></div></div><div class="custom-block tip"><p><a href="./../../markup/function/redirect.html">Twig-функция <code>redirect()</code></a> используется для постоянного перенаправления 301, когда slug не совпадает. <a href="./../../markup/filter/page.html">Twig-фильтр <code>|page</code></a> передаёт текущую страницу и перезаписывает URL-параметр <code>fullslug</code> на правильное значение.</p></div>`,30))])}const f=p(u,[["render",r]]);export{w as __pageData,f as default};
